import {setTitle} from '@github-ui/document-metadata'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useEffect} from 'react'

import {copilotAppLauncherAppBuilder} from '../config/app-builder'
import {CopilotAppLauncher} from '../src/CopilotAppLauncher'

interface CopilotAppLauncherPayload {
  open?: string | null
}

export default function CopilotAppLauncherPage() {
  const routePayload = useRoutePayload<CopilotAppLauncherPayload | undefined>()
  const embeddedPayload = copilotAppLauncherAppBuilder.getEmbeddedData()?.payload as
    | CopilotAppLauncherPayload
    | undefined
  const open = routePayload && 'open' in routePayload ? routePayload.open : embeddedPayload?.open

  useEffect(() => {
    setTitle('Open GitHub Copilot · GitHub')
  }, [])

  return <CopilotAppLauncher open={open} />
}
