import {WithShimmerEffect} from '@github-ui/copilot-chat/components/WithShimmerEffect'
import {MarkGithubIcon, TriangleDownIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Button, ButtonGroup, Heading, IconButton, Link, LinkButton} from '@primer/react'
import {Fragment} from 'react'

import styles from './CopilotAppLauncher.module.css'
import type {ContinueLink} from './deep-link'
import type {DownloadItem} from './download-options'
import {WordReveal, type WordRevealSegment} from './WordReveal'

type ActionVariant = 'default' | 'primary'
export type WaitingAnimation = 'none' | 'preview' | 'loop'
const GITHUB_APP_LANDING_PAGE_URL = 'https://github.com/features/ai/github-app'
export const COPILOT_APP_LAUNCHER_MOBILE_UNSUPPORTED_STATUS_MESSAGE =
  'Visit this page on your computer to open the app.'

const WAITING_SEGMENTS: WordRevealSegment[] = [{text: 'Opening in GitHub Copilot app...', className: styles.TitleMuted}]
const MOBILE_SEGMENTS: WordRevealSegment[] = [
  {text: 'GitHub Copilot app', className: ''},
  {text: ' is available on macOS, Windows, and Linux.', className: styles.TitleMuted},
]
const EXPIRED_SEGMENTS: WordRevealSegment[] = [
  {text: 'GitHub Copilot app', className: ''},
  {text: ' may not be installed.', className: styles.TitleMuted},
]

interface DownloadActionMenuProps {
  downloadItem: DownloadItem
  downloadItems: readonly DownloadItem[]
  variant: ActionVariant
}

function DownloadActionMenu({downloadItem, downloadItems, variant}: DownloadActionMenuProps) {
  return (
    <ButtonGroup className={styles.DownloadButtonGroup}>
      <LinkButton href={downloadItem.href} variant={variant} size="large" className={styles.DownloadMainButton}>
        {downloadItem.label}
      </LinkButton>
      <ActionMenu>
        <ActionMenu.Anchor>
          <IconButton
            icon={TriangleDownIcon}
            variant={variant}
            size="large"
            aria-label="Choose a GitHub Copilot app download"
            className={styles.DownloadMenuButton}
          />
        </ActionMenu.Anchor>
        <ActionMenu.Overlay align="end">
          <ActionList>
            {downloadItems.map((item, index) => {
              const previousItem = downloadItems[index - 1]
              const showDivider = previousItem && previousItem.platform !== item.platform
              return (
                <Fragment key={item.label}>
                  {showDivider && <ActionList.Divider key={`divider-${item.label}`} />}
                  <ActionList.LinkItem href={item.href}>{item.label}</ActionList.LinkItem>
                </Fragment>
              )
            })}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    </ButtonGroup>
  )
}

export interface CopilotAppLauncherViewProps {
  isExpired: boolean
  isMobileUnsupported: boolean
  waitingAnimation: WaitingAnimation
  useExpiredActionAffordance: boolean
  onRetry: () => void
  downloadItem: DownloadItem
  downloadItems: readonly DownloadItem[]
  continueLink: ContinueLink
}

export function getCopilotAppLauncherStatusMessage(isExpired: boolean) {
  return isExpired
    ? 'Download it to get started, or try opening again.'
    : 'Launching the desktop app, this should only take a moment...'
}

export function CopilotAppLauncherView({
  isExpired,
  isMobileUnsupported,
  waitingAnimation,
  useExpiredActionAffordance,
  onRetry,
  downloadItem,
  downloadItems,
  continueLink,
}: CopilotAppLauncherViewProps) {
  const statusMessage = isMobileUnsupported
    ? COPILOT_APP_LAUNCHER_MOBILE_UNSUPPORTED_STATUS_MESSAGE
    : getCopilotAppLauncherStatusMessage(isExpired)
  const retryLabel = useExpiredActionAffordance ? 'Retry' : 'Open the app'
  const retryVariant: ActionVariant = 'primary'
  const downloadVariant: ActionVariant = 'default'
  const continueCopy = 'View on'
  const hasWaitingShimmer = waitingAnimation !== 'none'
  const segments = isMobileUnsupported ? MOBILE_SEGMENTS : isExpired ? EXPIRED_SEGMENTS : WAITING_SEGMENTS
  const ctaClassName = styles.CtaReveal
  const title = (
    <WordReveal baseDelay={200} wordDelay={50}>
      {segments}
    </WordReveal>
  )

  return (
    <div className={styles.CopilotAppLauncher}>
      <section className={styles.Window} aria-labelledby="copilot-app-launcher-title">
        <div className={styles.Content}>
          <div className={styles.Welcome}>
            <MarkGithubIcon size={48} className={styles.Logo} aria-hidden="true" />

            <div className={styles.Intro}>
              {hasWaitingShimmer && !isExpired ? (
                <WithShimmerEffect className={styles.ShimmerTitle}>
                  <Heading as="h1" className={styles.Title} id="copilot-app-launcher-title">
                    {title}
                  </Heading>
                </WithShimmerEffect>
              ) : (
                <Heading as="h1" className={styles.Title} id="copilot-app-launcher-title">
                  {title}
                </Heading>
              )}
              <p key={statusMessage} className={`${styles.Description} ${ctaClassName}`}>
                {statusMessage}
              </p>
            </div>

            <div className={`${styles.Actions} ${ctaClassName}`}>
              {isMobileUnsupported ? (
                <LinkButton
                  href={GITHUB_APP_LANDING_PAGE_URL}
                  variant="primary"
                  size="large"
                  className={styles.ActionButton}
                >
                  Discover GitHub Copilot app
                </LinkButton>
              ) : (
                <>
                  <Button
                    variant={retryVariant}
                    size="large"
                    onClick={onRetry}
                    disabled={useExpiredActionAffordance && !isExpired}
                    className={styles.ActionButton}
                  >
                    {retryLabel}
                  </Button>
                  <DownloadActionMenu
                    downloadItem={downloadItem}
                    downloadItems={downloadItems}
                    variant={downloadVariant}
                  />
                </>
              )}
            </div>

            {!isMobileUnsupported && (
              <p className={`${styles.HelpText} ${ctaClassName}`}>
                {continueCopy}{' '}
                <Link
                  href={continueLink.href}
                  inline
                  className="Link--inTextBlock"
                  aria-label={`${continueCopy} GitHub.com`}
                >
                  GitHub.com
                </Link>
                {' · '}
                <Link href={GITHUB_APP_LANDING_PAGE_URL} inline className="Link--inTextBlock">
                  Discover the app
                </Link>
              </p>
            )}
          </div>
        </div>
      </section>
    </div>
  )
}
