import {useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore} from 'react'

const ACCEPTED_SCHEMES = ['ghapp://', 'github-app://', 'gh://'] as const
const GITHUB_HOME_URL = 'https://github.com'
const GITHUB_HOST = 'github.com'
export const DEFAULT_DEEP_LINK = 'ghapp://'
export const LAUNCH_DELAY_MS = 500
export const EXPIRED_DELAY_MS = 4000

export type LaunchDisplayState = 'waiting' | 'success' | 'expired'
export type LaunchDeepLink = (deepLink: string) => void
export type ContinueLinkKind = 'continue' | 'goBack'

export interface ContinueLink {
  href: string
  kind: ContinueLinkKind
}

interface UseDeepLinkLaunchOptions {
  target: string
  displayState?: LaunchDisplayState
  launchDeepLink: LaunchDeepLink
  shouldAutoLaunch?: boolean
}

export function decodeOpenTarget(search: string) {
  return new URLSearchParams(search).get('open')
}

export function isAcceptedDeepLink(target: string) {
  const normalizedTarget = target.toLowerCase()
  return ACCEPTED_SCHEMES.some(scheme => normalizedTarget.startsWith(scheme))
}

export function resolveLaunchTarget(target: string | null) {
  return target && isAcceptedDeepLink(target) ? target : DEFAULT_DEEP_LINK
}

export function getGitHubContinueUrl(target: string | null) {
  if (!target || !isAcceptedDeepLink(target)) return undefined

  try {
    const targetUrl = new URL(target, GITHUB_HOME_URL)
    if (targetUrl.hostname.toLowerCase() !== GITHUB_HOST) return undefined

    return `${GITHUB_HOME_URL}${targetUrl.pathname}${targetUrl.search}${targetUrl.hash}`
  } catch {
    return undefined
  }
}

export function resolveContinueLink(target: string | null, referrer: string): ContinueLink {
  const githubContinueUrl = getGitHubContinueUrl(target)
  if (githubContinueUrl) {
    return {
      href: githubContinueUrl,
      kind: 'continue',
    }
  }

  return {
    href: referrer || GITHUB_HOME_URL,
    kind: 'goBack',
  }
}

function getBrowserReferrer() {
  return typeof document === 'undefined' ? '' : document.referrer
}

function getServerReferrer() {
  return ''
}

function subscribeToReferrer() {
  return () => {}
}

export function useContinueLink(target: string | null) {
  const referrer = useSyncExternalStore(subscribeToReferrer, getBrowserReferrer, getServerReferrer)
  return useMemo(() => resolveContinueLink(target, referrer), [target, referrer])
}

export function defaultLaunchDeepLink(deepLink: string) {
  if (typeof window === 'undefined') return
  window.location.href = deepLink
}

export function useDeepLinkLaunch({
  target,
  displayState,
  launchDeepLink,
  shouldAutoLaunch = true,
}: UseDeepLinkLaunchOptions) {
  const [status, setStatus] = useState<LaunchDisplayState>('waiting')
  const [hasExpired, setHasExpired] = useState(false)
  const cleanupRef = useRef<(() => void) | undefined>(undefined)

  const attemptLaunch = useCallback(() => {
    cleanupRef.current?.()

    const launchTimer = window.setTimeout(() => launchDeepLink(target), LAUNCH_DELAY_MS)
    const fallbackTimer = window.setTimeout(() => {
      removeSuccessListeners()
      setStatus('expired')
      setHasExpired(true)
    }, EXPIRED_DELAY_MS)

    function removeSuccessListeners() {
      window.removeEventListener('blur', handleLaunchSuccessSignal)
      window.removeEventListener('pagehide', handleLaunchSuccessSignal)
      document.removeEventListener('visibilitychange', handleVisibilityChange)
    }

    function handleLaunchSuccessSignal() {
      window.clearTimeout(fallbackTimer)
      removeSuccessListeners()
      setStatus('success')
    }

    function handleVisibilityChange() {
      if (document.visibilityState === 'hidden') {
        handleLaunchSuccessSignal()
      }
    }

    window.addEventListener('blur', handleLaunchSuccessSignal)
    window.addEventListener('pagehide', handleLaunchSuccessSignal)
    document.addEventListener('visibilitychange', handleVisibilityChange)

    const cleanup = () => {
      window.clearTimeout(launchTimer)
      window.clearTimeout(fallbackTimer)
      removeSuccessListeners()
    }

    cleanupRef.current = cleanup
    return cleanup
  }, [launchDeepLink, target])

  const handleRetry = useCallback(() => {
    setStatus('waiting')
    attemptLaunch()
  }, [attemptLaunch])

  useEffect(() => {
    if (!shouldAutoLaunch) return

    attemptLaunch()
    return () => cleanupRef.current?.()
  }, [attemptLaunch, shouldAutoLaunch])

  const visibleState = displayState ?? status

  return {
    visibleState,
    isExpired: visibleState === 'expired',
    useExpiredActionAffordance: hasExpired || visibleState === 'expired',
    handleRetry,
  }
}
