import {useSearchParams} from '@github-ui/react-router'
import {announce} from '@github-ui/aria-live'
import {isMobile} from '@github-ui/get-os'
import {useEffect, useEffectEvent, useMemo, useState, useSyncExternalStore} from 'react'

import {
  COPILOT_APP_LAUNCHER_MOBILE_UNSUPPORTED_STATUS_MESSAGE,
  CopilotAppLauncherView,
  getCopilotAppLauncherStatusMessage,
  type WaitingAnimation,
} from './CopilotAppLauncherView'
import {
  defaultLaunchDeepLink,
  resolveLaunchTarget,
  useContinueLink,
  useDeepLinkLaunch,
  type LaunchDeepLink,
  type LaunchDisplayState,
} from './deep-link'
import {DOWNLOAD_ITEMS, useResolvedDownloadItem} from './download-options'

export type {LaunchDisplayState} from './deep-link'
export {decodeOpenTarget, isAcceptedDeepLink} from './deep-link'

export const READY_TO_LAUNCH_DELAY_MS = 100

export interface CopilotAppLauncherProps {
  /**
   * Decoded app deep link. When omitted, the launcher reads the `open` query
   * parameter from the current route.
   */
  open?: string | null
  /**
   * Overrides the timeout-driven visual state. Use this for Storybook and
   * tests; omit it in production so the launcher can transition naturally.
   */
  displayState?: LaunchDisplayState
  /**
   * Launch implementation used by tests and Storybook. Production uses
   * `window.location.href = deepLink`.
   */
  launchDeepLink?: LaunchDeepLink
  /**
   * Shows a short waiting animation preview for static Storybook states without
   * enabling launch side effects.
   */
  animateWaitingState?: boolean
  /**
   * Overrides mobile detection for Storybook and tests. Mobile browsers do not
   * attempt app deep-link launches yet.
   */
  isMobileDevice?: boolean
}

function subscribeToMobileDevice() {
  return () => {}
}

function getBrowserMobileDevice() {
  return isMobile()
}

function getServerMobileDevice() {
  return undefined
}

function useDetectedMobileDevice() {
  return useSyncExternalStore(subscribeToMobileDevice, getBrowserMobileDevice, getServerMobileDevice)
}

function useReadyToLaunch() {
  const [isReadyToLaunch, setIsReadyToLaunch] = useState(false)

  useEffect(() => {
    const readyTimer = window.setTimeout(() => setIsReadyToLaunch(true), READY_TO_LAUNCH_DELAY_MS)
    return () => window.clearTimeout(readyTimer)
  }, [])

  return isReadyToLaunch
}

export function CopilotAppLauncher({
  open,
  displayState,
  launchDeepLink = defaultLaunchDeepLink,
  animateWaitingState = false,
  isMobileDevice: isMobileDeviceOverride,
}: CopilotAppLauncherProps) {
  const [searchParams] = useSearchParams()
  const detectedIsMobileDevice = useDetectedMobileDevice()
  const isMobileDevice = isMobileDeviceOverride ?? detectedIsMobileDevice
  const isReadyToLaunch = useReadyToLaunch()
  const queryTarget = useMemo(() => searchParams.get('open'), [searchParams])
  const target = open === undefined ? queryTarget : open
  const launchTarget = resolveLaunchTarget(target)
  const shouldUseDesktopLaunchPath = displayState === undefined && isMobileDevice === false
  const {visibleState, isExpired, useExpiredActionAffordance, handleRetry} = useDeepLinkLaunch({
    target: launchTarget,
    displayState,
    launchDeepLink,
    shouldAutoLaunch: shouldUseDesktopLaunchPath && isReadyToLaunch,
  })
  const downloadItem = useResolvedDownloadItem()
  const statusMessage = getCopilotAppLauncherStatusMessage(isExpired)
  const announceableStatusMessage =
    displayState === undefined
      ? isMobileDevice === true
        ? COPILOT_APP_LAUNCHER_MOBILE_UNSUPPORTED_STATUS_MESSAGE
        : isMobileDevice === false
          ? isReadyToLaunch
            ? statusMessage
            : undefined
          : undefined
      : undefined
  const continueLink = useContinueLink(launchTarget)
  const waitingAnimation: WaitingAnimation =
    isMobileDevice === true
      ? 'none'
      : visibleState === 'waiting'
        ? displayState === 'waiting'
          ? animateWaitingState
            ? 'preview'
            : 'none'
          : 'loop'
        : 'none'
  const announceStatusMessage = useEffectEvent((message?: string) => {
    if (!message) return

    announce(message)
  })

  useEffect(() => {
    announceStatusMessage(announceableStatusMessage)
  }, [announceableStatusMessage])

  return (
    <CopilotAppLauncherView
      isExpired={isExpired}
      isMobileUnsupported={isMobileDevice === true}
      waitingAnimation={waitingAnimation}
      useExpiredActionAffordance={useExpiredActionAffordance}
      onRetry={handleRetry}
      downloadItem={downloadItem}
      downloadItems={DOWNLOAD_ITEMS}
      continueLink={continueLink}
    />
  )
}

CopilotAppLauncher.displayName = 'CopilotAppLauncher'
